"প্রতিটা সফল রেফারে ১০০ পয়েন্ট পাবেন (নতুন ইউজার অন্তত ২৪ ঘণ্টা অ্যাপ রাখলে)।": "Get 100 points for each successful referral (if the new user keeps the app for at least 24 hours).",
"আপনার করা লিস্টিং অ্যাডমিন অনুমোদন (Approve) করলে ১০ পয়েন্ট পাবেন। প্রতিটা লিস্টিংয়ে একবারই পয়েন্ট দেওয়া হয়।": "Get 10 points when the admin approves your listing. Points are given once per listing.",
"সরাসরি প্রকাশিত হওয়া পোস্ট (যেমন শপের প্রোডাক্ট) এবং অ্যাডমিন যে পোস্ট আপনার পক্ষ থেকে দেয় সেগুলোতে পয়েন্ট নেই।": "No points for posts published directly (like shop products) or posts the admin makes on your behalf.",
