"রেফারের নিয়ম": "Referral rules",
"আপনার ইউনিক লিংক থেকে কেউ স্মার্ট ফেনী অ্যাপ ডাউনলোড করে সাইন আপ করলে ১টা রেফার সম্পন্ন হবে।": "A referral is complete when someone downloads the Smart Feni app from your unique link and signs up.",
"নতুন ইউজারকে অবশ্যই আপনার লিংকে ক্লিক করে Google Play থেকে অ্যাপ ইনস্টল করতে হবে। অন্য কোনোভাবে ইনস্টল হলে রেফার ধরা যাবে না।": "The new user must click your link and install the app from Google Play. Installs any other way won't count.",
"একটা ফোনে একবারের বেশি রেফার কাউন্ট হয় না। একই ফোন বা একই নম্বর দিয়ে আবার সাইন আপ করলে নতুন রেফার গণ্য হবে না।": "A phone counts for only one referral. Signing up again with the same phone or number won't count.",
"নিজের লিংকে নিজে সাইন আপ করলে রেফার গণ্য হবে না।": "Signing up with your own link doesn't count.",
"আপনার নিজের ফোনে, বা আগে থেকে অন্য কোনো অ্যাকাউন্ট আছে এমন ফোনে সাইন আপ হলে রেফার গণ্য হবে না।": "Sign-ups on your own phone, or on a phone that already has another account, don't count.",
"সাইন আপের পর রেফারটি অপেক্ষমাণ থাকে। নতুন ইউজার ২৪ ঘণ্টা অ্যাপ ইনস্টল রাখলে সাধারণত ২৪-২৭ ঘণ্টার মধ্যে ১০০ পয়েন্ট যোগ হয়ে যায় এবং আপনি নোটিফিকেশন পাবেন।": "After sign-up the referral is pending. If the new user keeps the app installed for 24 hours, 100 points are usually added within 24–27 hours and you'll be notified.",
"এই ২৪ ঘণ্টার মধ্যে নতুন ইউজার অ্যাপ আনইনস্টল করলে রেফারটি গণ্য হবে না।": "If the new user uninstalls the app within those 24 hours, the referral won't count.",
"উইথড্রের জন্য আপনার লিংক সহ একটা সোশ্যাল মিডিয়া পোস্ট করা বাধ্যতামূলক। তাই আগেই পোস্ট করে রাখুন।": "To withdraw you must make a social media post with your link. So post it in advance.",
