"উইথড্র করতে কমপক্ষে ১০০০ পয়েন্ট (৳১০০) লাগবে। এর কম হলে আবেদনের ফর্ম খুলবে না।": "You need at least 1000 points (৳100) to withdraw. Below that the form won't open.",
"পেমেন্ট শুধু বিকাশে (bKash) দেওয়া হয়। সঠিক ১১ ডিজিটের নম্বর দিন — ভুল নম্বরে পাঠানো টাকার দায় স্মার্ট ফেনী নেবে না।": "Payment is only via bKash. Enter the correct 11-digit number — Smart Feni isn't responsible for money sent to a wrong number.",
"আবেদনের সময় আপনার রেফার লিংক সহ সোশ্যাল মিডিয়া পোস্টের লিংক দিতে হবে। লিংক ছাড়া উইথড্র হবে না।": "When applying, give the link of a social media post containing your referral link. No withdrawal without it.",
"অ্যাডমিন পোস্ট ও আপনার তথ্য যাচাই করবেন। আবেদনের ২৪ ঘণ্টার মধ্যে যাচাই করে পেমেন্ট করা হবে।": "The admin will verify the post and your details. Payment is made within 24 hours of applying.",
