"ক্লিনিকের প্রতিনিধি হতে চাইলে স্মার্ট ফেনীর সাথে যোগাযোগ করুন। অ্যাডমিন নিয়োগ দিলে এখানে আপনার ক্লিনিক দেখা যাবে।": "To become a clinic representative, contact Smart Feni. Once the admin appoints you, your clinic shows here.",
"আমাদের সম্পর্কে | স্মার্ট ফেনী": "About us | Smart Feni",
"স্মার্ট ফেনী কী?": "What is Smart Feni?",
"স্মার্ট ফেনী ফেনী জেলার জন্য তৈরি একটি হাইপারলোকাল কমিউনিটি সার্ভিস প্ল্যাটফর্ম। আমাদের লক্ষ্য একটাই — ফেনীর ৬টা উপজেলার (ফেনী সদর, ছাগলনাইয়া, দাগনভূঞা, পরশুরাম, ফুলগাজী, সোনাগাজী) মানুষের প্রয়োজনীয় সব ধরনের স্থানীয় সেবা এক জায়গায় নিয়ে আসা।": "Smart Feni is a hyperlocal community service platform built for Feni district. Our single goal is to bring all the local services people need across Feni's 6 upazilas (Feni Sadar, Chhagalnaiya, Daganbhuiyan, Parshuram, Fulgazi, Sonagazi) into one place.",
"আমরা কী কী সেবা দিই": "The services we offer",
"বাসা ভাড়া, চাকরির খবর, রিপেয়ার সার্ভিস, গাড়ি ভাড়া, ব্লাড ডোনার, হোম মেস ফুড, টিউশন, স্বাস্থ্য ও আইনি পরামর্শ, লস্ট এন্ড ফাউন্ড সহ ১৮+ ধরনের সেবা — সবকিছু একটা প্ল্যাটফর্মে, ফেনীর মানুষের জন্য, ফেনীর মানুষের হাতে।": "House rent, job news, repair services, car rental, blood donors, home mess food, tuition, health and legal advice, lost & found and 18+ kinds of services — all on one platform, for the people of Feni, in the hands of the people of Feni.",
"আমাদের লক্ষ্য": "Our mission",
"\"প্রয়োজন আপনার, দায়িত্ব আমাদের\" — এই স্লোগানকে সামনে রেখে আমরা কাজ করি। আমরা বিশ্বাস করি স্থানীয় সেবা খোঁজা সহজ হওয়া উচিত, আর সেই সেবা হওয়া উচিত বিশ্বমানের। এখান থেকেই আমাদের ট্যাগলাইন: \"Global Standards. Local Service.\"": "\"Your need, our responsibility\" — we work with this slogan in mind. We believe finding local services should be easy, and those services should be world-class. Hence our tagline: \"Global Standards. Local Service.\"",
